#!/usr/bin/perl
# Direct Schur-side check (Marino-Vafa formula, no Hodge data) of the u_k-linear mKP equations P_k(D) tau_0.tau_1 = 0,
# tau_0 = Z(p), tau_1 = Z(e^{tau x} o p), in the F/A/S form generated by mkp_eqs.pm.
# f_mu = x^{|mu|} [p_mu] log Z (power series in x, mvlib::mv_conn), a_mu = (e^{tau x |mu|} - 1) f_mu, s_mu = 2 f_mu + a_mu.
# For each monomial p_nu, |nu| <= d:  x^{|nu|+k} [p_nu] P_k = Sum_terms c Sum_{nu = nu_1 + ... + nu_q} prod_a mult_a g_a(nu_a + ins_a)
# must vanish through x^P.  Control: the same with the sign of every A-factor flipped.
# Usage: perl mv_hirota_direct.pl k tau d P
use strict; use warnings; use FindBin; use lib $FindBin::Bin; use Math::BigRat; use mvlib (); use mkp_eqs;
$| = 1;
sub R { Math::BigRat->new(@_) }
my ($k, $taus, $d, $P) = @ARGV; my $tau = R($taus);
my $terms = mkp_eqs::eq_k($k);
print "equation k=$k: ", mkp_eqs::show($terms), "\n";
my %F;
sub f_of { my @mu = sort { $b <=> $a } @_; my $key = join(',', @mu); $F{$key} //= mvlib::mv_conn(\@mu, $tau, $P); $F{$key} }
sub expm1 { my ($c) = @_; my @e = map { R(0) } 0..$P; my $t = R(1); for my $n (0..$P) { $e[$n] = $t; $t = $t * $c / ($n + 1); } $e[0] -= 1; \@e }
my %G;
sub g_of { my ($type, $sgnA, @mu) = @_; my @s = sort { $b <=> $a } @mu; my $key = "$type|$sgnA|" . join(',', @s); return $G{$key} if exists $G{$key};
  my $f = f_of(@s); my $n = 0; $n += $_ for @s; my $a = mvlib::ser_mul(expm1($tau * $n), $f, $P); $a = mvlib::ser_scal(R($sgnA), $a);
  my $v = $type eq 'A' ? $a : mvlib::ser_add(mvlib::ser_scal(R(2), $f), $a); $G{$key} = $v; $v }
sub cnt { my %c; $c{$_}++ for @_; \%c }
sub mult { my ($nu, $ins) = @_; my $cn = cnt(@$nu); my $ci = cnt(@$ins); my $m = R(1);
  for my $v (keys %$ci) { my $a = $cn->{$v} // 0; for my $t (1..$ci->{$v}) { $m *= ($a + $t); } } $m }
sub submultisets { my @nu = @_; my $c = cnt(@nu); my @vals = sort { $a <=> $b } keys %$c; my @subs = ([]);
  for my $v (@vals) { my @new; for my $s (@subs) { for my $i (0..$c->{$v}) { push @new, [@$s, ($v) x $i]; } } @subs = @new; } @subs }
sub minus { my ($nu, $s) = @_; my $c = cnt(@$s); my @r; for my $v (@$nu) { if (($c->{$v} // 0) > 0) { $c->{$v}--; } else { push @r, $v; } } \@r }
sub decomps { my ($nu, $q) = @_; return ([[@$nu]]) if $q == 1; my @out;
  for my $s (submultisets(@$nu)) { my $rest = minus($nu, $s); for my $d2 (decomps($rest, $q - 1)) { push @out, [$s, @$d2]; } } @out }
sub eval_eq { my ($nu, $sgnA) = @_; my $tot = mvlib::ser_zero($P);
  for my $t (@$terms) { my ($c, $fac) = @$t; my $q = scalar @$fac;
    for my $dc (decomps($nu, $q)) { my $prod; my $mc = R(1);
      for my $a (0..$q-1) { my ($type, $ins, $u) = @{$fac->[$a]}; my @insall = (@$ins, (1) x $u);
        $mc *= mult($dc->[$a], \@insall); my $g = g_of($type, $sgnA, @{$dc->[$a]}, @insall);
        $prod = defined $prod ? mvlib::ser_mul($prod, $g, $P) : $g; }
      $tot = mvlib::ser_add($tot, mvlib::ser_scal($c * $mc, $prod)); } }
  $tot }
my @nus; for my $n (0..$d) { push @nus, mvlib::partitions($n); }
my ($nn, $bad, $badc) = (0, 0, 0);
for my $nu (@nus) { my $v = eval_eq($nu, 1); my $w = eval_eq($nu, -1);
  my @nz = grep { !$v->[$_]->is_zero } 0..$P; my @nzw = grep { !$w->[$_]->is_zero } 0..$P; $nn++; $bad++ if @nz; $badc++ if @nzw;
  printf "nu = (%s): %s ; control (A -> -A): %s\n", join(',', @$nu), (@nz ? "NONZERO at x^(@nz)" : "0 through x^$P"), (@nzw ? "nonzero" : "zero"); }
printf "SUMMARY k=%d tau=%s d=%d P=%d: %d monomials, %d failures; control nonzero in %d of %d\n", $k, $taus, $d, $P, $nn, $bad, $badc, $nn;
